L(OA8, 4,
  "Este cuaderno, lápiz y las situaciones de la clase.",
  "Aprenderé a decidir si sigo leyendo, releo o cambio de texto, y a dar razones.",
  ["Elijo textos con portada e índice.", "Registro mis lecturas."],
  ["A veces un libro nos atrapa y otras veces no. Está bien cambiar de libro si no te gusta, pero con razones. También puedes seguir si la dificultad es pasajera. Tienes tres decisiones: continuar, releer o cambiar de texto.",
   "Continúa si la historia te interesa aunque haya palabras difíciles. Relee una parte si no entendiste. Cambia de texto si tras varias páginas no te interesa o es muy difícil. No es abandono sin razón; es una decisión informada. Esto se llama abandono justificado.",
   "Pregúntate: ¿entiendo la mayor parte? ¿me da ganas de seguir? ¿hay un momento para pedir ayuda? Con tus respuestas, decides. Anótalo en tu registro."],
  [("continuar", "seguir leyendo"), ("releer", "volver a leer una parte"), ("cambiar", "elegir otro texto"), ("abandono justificado", "dejar un libro con una buena razón"), ("decisión", "lo que elijo hacer")],
  [("Continuar", "Leíste 10 páginas de un cuento de dragones. Te gusta y hay solo dos palabras difíciles. ¿Qué decides?", ["Me interesa.", "Las palabras difíciles son pocas.", "Sigo."], "Continuar leyendo"),
   ("Releer", "Un párrafo te confundió. ¿Qué haces?", ["No entendí.", "Vuelvo atrás."], "Releer ese párrafo")],
  [("Dejar el libro sin pensar.", "No sé si era un problema pasajero.", "Piensa si lo entiendes y te interesa."), ("Seguir un libro que no entiendo nada.", "Me aburro.", "Cambia con una razón.")],
  ([E("Un cuento te gusta y quieres saber cómo termina. ¿Qué decides?", "Continuar", "Si te interesa, conviene seguir leyendo."),
    E("No entendiste una parte. ¿Qué haces: releer o cambiar de libro?", "Releer", "Una parte confusa se puede aclarar."),
    E("¿Está bien cambiar de libro si no me gusta?", "Sí, con razón", "Es un abandono justificado.")],
   [E("Libro con 20 palabras difíciles por página, y no entiendes casi nada. ¿Qué decides: cambiar o continuar?", "Cambiar", "Es muy difícil por ahora."),
    E("Libro de aventuras que te encanta, con tres palabras difíciles. ¿Qué decides?", "Continuar", "Las palabras no impiden entender."),
    E("¿Qué es un abandono justificado?", "Dejar un libro con una buena razón", "Se explica por qué.")],
   [E("Leíste 15 páginas y no entiendes la historia. Un párrafo te perdió. ¿Qué haces primero?", "Releer ese párrafo", "Puedes aclarar antes de cambiar."),
    E("Leíste 20 páginas de un libro de insectos y te aburre porque ya sabías todo. ¿Qué decides?", "Cambiar", "No te aporta nada nuevo."),
    E("El libro te gusta, pero hay una palabra rara. ¿Qué haces?", "Pido ayuda o la busco", "Se resuelve y sigo.")],
   [E("Dos niños dejan un libro: Ana dice «Me aburrió» sin razón. Beto dice «Ya sé todo lo que cuenta». ¿Quién justificó mejor?", "Beto", "Dio una razón."),
    E("¿Por qué es mejor releer antes de cambiar de texto cuando algo no se entiende?", "Porque puede ser solo una parte confusa", "Quizá se aclare al releer.")],
   [E("Eliges entre: A) seguir un libro que entiendes y te gusta; B) cambiar a otro porque el tuyo es fácil y divertido. ¿Qué decisión tiene sentido?", "A", "No hay razón para cambiar."),
    E("Escribe una razón justificada para cambiar de libro.", "Es muy difícil para mí ahora", "Es una razón válida.")]),
  [E("Llevas 8 páginas de un libro de misterio. Te gusta, aunque hay tres palabras nuevas. ¿Qué decides?", "Continuar", "Te interesa y puedes entenderlo.")],
  [E("¿Puedo pedir ayuda con palabras difíciles?", "Sí", "Es una estrategia."),
   E("¿Cambiar de libro es siempre malo?", "No", "Si hay razón, está bien."),
   E("¿Qué hago si algo no se entiende?", "Releer", "Aclara la parte confusa.")],
  ("Lee estos casos y decide para cada uno si continúas, relees o cambias. Escribe una razón. A) Libro de cuentos que te encanta, 3 palabras nuevas. B) Un párrafo que no entendiste. C) Libro muy difícil donde no entiendes casi nada tras 10 páginas.", "A) Continúo porque me gusta. B) Releo el párrafo porque no lo entendí. C) Cambio de libro porque es muy difícil ahora.", ["decide en los tres casos", "da una razón para cada uno", "razones coherentes"], ["tres decisiones"], ["decidir sin razón", "cambiar todo"], "Comparte tus decisiones y escucha otras opiniones."),
  "Piensa en un libro que dejaste y escribe una razón.",
  "Escribe qué harías si un libro te gusta pero tiene muchas palabras difíciles.")

L(OA8, 5,
  "Este cuaderno, lápiz y los modelos de recomendación de la clase.",
  "Aprenderé a recomendar una lectura a otra persona desde mi experiencia.",
  ["Registro mis lecturas.", "Doy razones sobre lo que leo."],
  ["Recomendar una lectura es compartir un hallazgo. Un buen hallazgo se cuenta con tres partes: qué leí, qué parte me gustó y por qué creo que a otra persona le puede gustar. Esto ayuda a que más personas disfruten.",
   "Ejemplo: «Leí «El viaje de la gota». Me gustó cuando la gota llega al mar. Te lo recomiendo porque tiene dibujos y se lee rápido». La recomendación tiene título, una parte favorita y una razón.",
   "Una recomendación honesta cuenta lo que realmente sentiste. No necesitas decir que todo era perfecto. También puedes decir a quién se la recomiendas: a alguien que le gusten los animales, las aventuras o los poemas."],
  [("recomendar", "sugerir una lectura"), ("hallazgo", "descubrimiento que quiero compartir"), ("parte favorita", "lo que más me gustó"), ("razón", "dato que apoya mi recomendación"), ("honesto", "que dice lo que realmente piensa")],
  [("Reconocer una buena recomendación", "«Leí «El viaje de la gota». Me gustó cuando la gota llega al mar. Te lo recomiendo porque tiene dibujos». ¿Qué libro recomienda?", ["Busco el título.", "Dice El viaje de la gota."], "El viaje de la gota"),
   ("Reconocer la razón", "En la misma recomendación, ¿por qué lo recomienda?", ["Busco después de porque.", "Tiene dibujos."], "Porque tiene dibujos")],
  [("Decir solo «es bueno».", "No dice por qué.", "Cuenta una parte y una razón."), ("Copiar la recomendación de otro.", "No es mi experiencia.", "Cuenta lo que yo sentí.")],
  ([E("Recomendación: «Leí «Mi gato Pelusa». Me gustó cuando se esconde». ¿Qué libro leyó?", "Mi gato Pelusa", "La recomendación lo dice con claridad."),
    E("En esa recomendación, ¿cuál es la parte favorita?", "Cuando el gato se esconde", "Es lo que le gustó."),
    E("¿Una recomendación debe tener título?", "Sí", "Dice qué libro es.")],
   [E("¿Qué tres partes tiene una buena recomendación?", "Qué leí, qué parte me gustó y por qué", "Esas son las partes."),
    E("¿Qué palabra ayuda a dar la razón?", "Porque", "Introduce la razón."),
    E("¿Una recomendación puede decir a quién le puede gustar?", "Sí", "Ayuda a elegir.")],
   [E("Elige la mejor recomendación: A) «Es bueno». B) «Leí «Los planetas». Me gustó la parte de Saturno. Te lo recomiendo porque explica con dibujos». ¿Cuál es la mejor?", "B", "Tiene título, parte y razón."),
    E("Completa: «Te recomiendo «El zorro presumido» porque ___». Elige: a) tiene una enseñanza divertida; b) es una caja.", "a", "Es una razón sobre el texto."),
    E("A Vicky le gustan los animales. ¿Qué libro le recomiendas: «Mi gato Pelusa» o «Recetas de pan»?", "Mi gato Pelusa", "Se relaciona con su gusto.")],
   [E("Un niño dice «Léelo, es lo mejor» sin más. ¿Qué falta?", "Parte favorita y razón", "No explica qué le gustó ni por qué."),
    E("¿Por qué es mejor una recomendación honesta?", "Porque cuenta lo que realmente sentí", "Se puede confiar en ella.")],
   [E("Escribe una recomendación con estos datos: libro «El viaje de la gota», parte favorita: cuando llega al mar, razón: tiene dibujos.", "Leí «El viaje de la gota». Me gustó cuando llega al mar. Te lo recomiendo porque tiene dibujos.", "Usa las tres partes."),
    E("¿A quién le recomendarías «El viaje de la gota»: a alguien que quiere una historia con dibujos o a alguien que quiere recetas?", "A alguien que quiere una historia con dibujos", "Coincide con el libro.")]),
  [E("Tu amigo no sabe qué leer. Le dices: «Lee «Poemas del mar» porque tiene rimas divertidas». ¿Dio una razón?", "Sí", "Dice porque tiene rimas divertidas.")],
  [E("¿Recomendar es compartir un hallazgo?", "Sí", "Es contar lo que descubrí."),
   E("¿Debo mentir si no me gustó?", "No", "Debo ser honesto."),
   E("¿Qué ayuda más a elegir un libro: la parte favorita de quien lo leyó o el color de su mochila?", "La parte favorita de quien lo leyó", "Cuenta qué tiene el libro.")],
  ("Escribe una recomendación de una lectura que hayas hecho, o usa este modelo: libro «Poemas del mar», parte favorita: el poema donde las olas bailan, razón: suena como música. Debe tener: título, parte favorita, razón y a quién se la recomiendas.", "Leí «Poemas del mar». Me gustó el poema donde las olas bailan. Te lo recomiendo porque suena como música, a quien le gustan los poemas.", ["incluye título, parte favorita y razón", "dice a quién se la recomienda", "es honesta"], ["recomendación escrita"], ["decir solo es bueno", "no dar razón"], "Cuéntale tu recomendación a alguien y pregúntale si le dieron ganas de leerlo."),
  "Recomienda a alguien de casa una lectura con una razón.",
  "Escribe una recomendación para un compañero con un gusto distinto al tuyo.")
